// Pins Sha256.bigIntToBigInt output against known digests
describe("Sha256 hashing", () => {
    test('hashes "normal" bigint correctly', async () => {
        const result = await Sha256.bigIntToBigInt(12345678901234567890n)
        expect(result).toBe(
        56852366904620309955443196953958614839691482996345339438904049760800697048404n
        )
    })

    test("hashes 0 correctly", async () => {
        const result = await Sha256.bigIntToBigInt(0n)
        expect(result).toBe(
        102987336249554097029535212322581322789799900648198034993379397001115665086549n
        )
    })
})

// Parses big.Int blocks from a debug-print string into an array of bigints
function testArray(input: string): bigint[] {
    const result: bigint[] = []

    const blockRegex = /neg:\s*(true|false),\s*abs:\s*math\/big\.nat.*?\[(.*?)\]/g

    let match
    while ((match = blockRegex.exec(input)) !== null) {
        const isNegative = match[1] === "true"
        const limbsStr = match[2]!

        const limbs = limbsStr.split(",").map((s) => BigInt(s.trim()))

        // Reassemble little-endian: limb[i] occupies bits [64*i, 64*i+64).
        let value = 0n
        for (let i = 0; i < limbs.length; i++) {
            value += limbs[i]! << BigInt(i * 64)
        }

        result.push(isNegative ? -value : value)
    }

    return result
}

// debug-print map of big.Ints -> Record keyed by int; falls back to indexing a slice
function testMap(input: string): Record<number, bigint> {
    const result: Record<number, bigint> = {}

    const mapEntryRegex = /(\d+):\s*\*?{neg:\s*(true|false),\s*abs:\s*math\/big\.nat.*?\[(.*?)\]}/g

    let match
    let matchCount = 0

    while ((match = mapEntryRegex.exec(input)) !== null) {
        const key = Number(match[1])
        const isNegative = match[2] === "true"
        const limbsStr = match[3]!

        const limbs = limbsStr.split(",").map((s) => BigInt(s.trim()))
        let value = 0n
        for (let i = 0; i < limbs.length; i++) {
            value += limbs[i]! << BigInt(i * 64)
        }

        result[key] = isNegative ? -value : value
        matchCount++
    }

    // No keyed entries found: treat input as a plain slice and key by index.
    if (matchCount === 0) {
        const sliceRegex = /{neg:\s*(true|false),\s*abs:\s*math\/big\.nat.*?\[(.*?)\]}/g
        let index = 0
        while ((match = sliceRegex.exec(input)) !== null) {
            const isNegative = match[1] === "true"
            const limbsStr = match[2]!
            const limbs = limbsStr.split(",").map((s) => BigInt(s.trim()))
            let value = 0n
            for (let i = 0; i < limbs.length; i++) {
                value += limbs[i]! << BigInt(i * 64)
            }
            result[index++] = isNegative ? -value : value
        }
    }

    return result
}

